impl Solution {
    pub fn k_items_with_maximum_sum(num_ones: i32, num_zeros: i32, num_neg_ones: i32, k: i32) -> i32 {
        let mut ones_to_take = num_ones.min(k);
        let remaining = k - ones_to_take;
        let zeros_to_take = num_zeros.min(remaining);
        let remaining_after_zeros = k - ones_to_take - zeros_to_take;

        let mut sum = ones_to_take * 1 + zeros_to_take * 0;

        if remaining_after_zeros > 0 {
            let neg_ones_to_take = remaining_after_zeros.min(num_neg_ones);
            sum -= neg_ones_to_take * 1;
        }

        sum
    }
}

